window.__NOTES_DATA__ = {"schema":2,"generated_at":"2026-10-09T10:59:12.578348+00:00","stats":{"total":46,"by_area":{"math2_gaoshu":5,"math2_xiandai":5,"ds":1,"co":13,"os":8,"cn":14}},"notes":[{"id":"e7bfe8cf-22b7-4aed-a864-c381ab7f500f","revision":2,"study_area":"cn","title":"CRC 计算冗余码的五步（101001，G(X)=X³+X²+1）","body_markdown":"**CRC 冗余码（例：数据 $101001$，$G(X)=X^3+X^2+1$）**\n\n1. 被除数：数据后补「最高次数」个 0 → $101001000$。\n2. 除数：$G(X)$ 系数比特串 → $1101$。\n3. 模 2 除法（异或、不借位）求余 → 余 $1$。\n4. 余数位数不足最高次数则前补 0 → $001$。\n5. 冗余码接在数据后 → 实发 $101001001$。","supplement_markdown":"补 0 个数 = 最高次数；除数缺的次幂位要补 0（$X^3+X^2+1\\to1101$）。","content_form":"mixed","chapter":"计算机网络 · 数据链路层 · 差错检测（CRC 冗余码计算）","kp_tags":["CRC","模2除法","生成多项式","冗余码"],"source_label":"用户上传","images":["media/7ddf34b83f16daf9cab0037be679395cc2a6f2b0d1b2af34b50353798b78b89d.png"],"diagram":null},{"id":"e05687cb-d80d-44f7-bb57-b9e124908a5c","revision":2,"study_area":"cn","title":"HDLC 用零比特填充、PPP 用字符填充（默认异步线路）","body_markdown":"- **HDLC**：面向比特 → 零比特填充。\n- **PPP**：面向字节 → 异步线路（默认）用字符填充，同步线路才用零比特填充。","supplement_markdown":"「默认异步线路」这个前提直接决定 PPP 用字符填充。","content_form":"mixed","chapter":"计算机网络 · 数据链路层 · 封装成帧与透明传输（HDLC 与 PPP）","kp_tags":["HDLC","PPP","零比特填充","字符填充"],"source_label":"用户上传","images":["media/83f26e649a82c38a400d366346d0bd84e681f269719558a421734289b9071642.png"],"diagram":null},{"id":"b47aead8-6faf-485b-bca1-65401302709a","revision":2,"study_area":"cn","title":"MTU 最大传送单元：以太网 1500 字节","body_markdown":"MTU（最大传送单元）：数据链路层一帧能承载的最大数据量，以太网 MTU = 1500 字节。","supplement_markdown":"MTU 限制的是 IP 数据报总长度（首部+数据），超了就要分片。","content_form":"mixed","chapter":"计算机网络 · 网络层 · IPv4 数据报格式与分片（MTU）","kp_tags":["MTU","最大传送单元","1500 字节","IP 分片"],"source_label":"用户上传","images":["media/480009aa430ef52887c8400de99c7f144fc9254429647d0d821ee91570f7e36b.png"],"diagram":null},{"id":"ba2cb2f2-deed-4869-b3bd-134d365ef25d","revision":2,"study_area":"cn","title":"中继器与集线器：5-4-3 规则与冲突域","body_markdown":"- **中继器**：整形、放大并转发数字信号，延长距离（放大器放大的是模拟信号）。\n- **集线器**：多端口中继器。\n- 10BASE5 遵循 **5-4-3 规则**：4 个中继器串 5 段介质，只有 3 段可挂计算机。","supplement_markdown":"二者都在物理层，都不能分割冲突域（能分割的是网桥/交换机/路由器）。","content_form":"mixed","chapter":"计算机网络 · 物理层 · 物理层设备（中继器与集线器）","kp_tags":["中继器","集线器","5-4-3 规则","冲突域"],"source_label":"用户上传","images":["media/2ae721922ea68300d4e5ffd7f1519c48579e49e786eaf3c8f3b3f841260afdcc.png"],"diagram":null},{"id":"ac96e62c-f69c-4b26-b14f-03c6d9cc8473","revision":2,"study_area":"cn","title":"以太网 V2 的 MAC 帧格式与最大帧长","body_markdown":"**以太网 V2 MAC 帧（最大 1518 B）**\n\n| 目的地址 | 源地址 | 类型 | 数据载荷 | FCS |\n| --- | --- | --- | --- | --- |\n| 6 B | 6 B | 2 B | 46~1500 B | 4 B |","supplement_markdown":"发送顺序自左向右；最大 1518 = 6+6+2+1500+4，最小 64（下限 46 由 CSMA/CD 争用期决定）。","content_form":"mixed","chapter":"计算机网络 · 数据链路层 · 以太网与 MAC 帧格式","kp_tags":["以太网V2帧格式","MAC帧字段","最大帧长1518B","FCS"],"source_label":"用户上传","images":["media/7d3e9e672587b7c44dbc574af9848c0b3b1de95df1b5eda356f39d0b4ddaceb1.png"],"diagram":null},{"id":"b53e1d53-2ba6-42fe-8933-247fb4a10025","revision":2,"study_area":"cn","title":"四种二进制数字调制：只有 FSK 需要两个载波频率","body_markdown":"四种二进制数字调制中，**只有 FSK（频移键控）用两个不同频率载波**分别表示 0/1；ASK 改幅度、PSK/DPSK 改相位，都用单一频率。","supplement_markdown":"DPSK 的「差分」= 用相邻码元相位差表示数据，不需绝对相位参考。","content_form":"mixed","chapter":"计算机网络 · 物理层 · 编码与调制（数字调制）","kp_tags":["数字调制","FSK","ASK/PSK/DPSK","载波频率"],"source_label":"用户上传","images":["media/05ecff4af884abf90543aae17f0512439d5a821c7eb3ace8a53742bf7c12dee0.png"],"diagram":null},{"id":"3c17f112-8343-4c28-8a48-390cea7bf276","revision":2,"study_area":"cn","title":"奈氏准则与香农定理：两个极限速率公式","body_markdown":"- **奈氏准则**（理想低通、无噪声）：极限码元速率 $=2W\\log_2 V$，$W$ 带宽、$V$ 电平数。\n- **香农定理**（有高斯白噪声）：极限比特率 $C=W\\log_2(1+\\frac{S}{N})$，$\\frac{S}{N}$ 为信噪比；若给 dB，$\\text{dB}=10\\log_{10}\\frac{S}{N}$。","supplement_markdown":"奈氏管码元速率（只关 $V$），香农管比特率（只关信噪比）；有噪声时两条都算取更小。","content_form":"mixed","chapter":"计算机网络 · 物理层 · 信道的极限容量（奈奎斯特定理与香农定理）","kp_tags":["奈氏准则","香农定理","码元传输速率","信噪比"],"source_label":"用户上传","images":["media/755ee0dc29caafeb022f322cbd589fc256ba637adbf9d92d550b1b11fc10c43c.png"],"diagram":null},{"id":"e1a30512-e1a4-4bec-82ff-3706cda776ef","revision":2,"study_area":"cn","title":"字节填充：用 ESC 转义 SOH/EOT 实现透明传输","body_markdown":"**字节填充（透明传输）**：发送端在数据的 SOH/EOT 前插入转义字符 ESC，ESC 本身出现则再插一个 ESC；接收端删除这些 ESC。","supplement_markdown":"对照比特填充（HDLC）：数据里凑满 5 个连续 1 就插一个 0，接收端删掉。","content_form":"mixed","chapter":"计算机网络 · 数据链路层 · 封装成帧与透明传输（字节填充）","kp_tags":["字节填充","转义字符 ESC","SOH/EOT","透明传输"],"source_label":"用户上传","images":["media/99eeaaa913b54065b0e33c849928ad4a20ff336ed149b60149f5bb202cb4485d.png"],"diagram":null},{"id":"c84147a6-308d-4092-853b-74c798ed4d1e","revision":3,"study_area":"cn","title":"常用数字数据编码：NRZ / RZ / NRZI / 曼彻斯特 / 差分曼彻斯特","body_markdown":"**常用数字数据编码**\n\n- NRZ：码元内电平不回零。\n- RZ：每个码元中间跳回零。\n- NRZI：电平不变=1、跳变=0。\n- 曼彻斯特：每码元中间必跳变，跳变方向表示数据（10Base-T 用它）。\n- 差分曼彻斯特：中间跳变只做时钟，数据看码元**起始处有无跳变**（无=1、有=0）。","supplement_markdown":"只有两种曼彻斯特是「每码元中间必跳变」；曼彻斯特用于早期 10Base-T，吉比特以太网不用它。","content_form":"mixed","chapter":"计算机网络 · 物理层 · 编码与调制（数字数据编码）","kp_tags":["不归零 NRZ","归零 RZ","反向非归零 NRZI","曼彻斯特/差分曼彻斯特","10Base-T"],"source_label":"用户上传","images":["media/c40b44bba9bc87a6484adc1d7b8264a644e18516b7ef19b2a365d9cc9390fc0d.png","media/23c52d7ba5d5f0732e876cdd85ed689c6481268176c621e09e2b46b9c974b1e1.png"],"diagram":null},{"id":"4b049192-c11e-49f4-8210-140b1bd7498a","revision":2,"study_area":"cn","title":"无差错接受：凡接收的帧都认为没有传输差错","body_markdown":"**无差错接受**：凡接收的帧（不含丢弃的）都以接近 1 的概率认为无传输差错——有差错就丢弃。要做到**可靠传输**（发什么收什么）还需**序号、确认、重传**。","supplement_markdown":"无差错接受=收到就没错（出错丢弃）；可靠传输还要发什么收什么，以太网可只做到前者。","content_form":"mixed","chapter":"计算机网络 · 数据链路层 · 可靠传输的基本概念（无差错接受）","kp_tags":["无差错接受","可靠传输","序号/确认/重传","丢弃差错帧"],"source_label":"用户上传","images":["media/d4ef78894f7188d4bd85e8b9a42f41d860860daae7a7b440aff7739e5d26e80d.png"],"diagram":null},{"id":"f1d55462-71fa-4fd5-9831-81c3ba4fb3aa","revision":2,"study_area":"cn","title":"熟知端口：DNS 53 / HTTP 80 / FTP 控制 21","body_markdown":"熟知端口：DNS 53、HTTP 80、FTP 控制 21。端口是传输层逻辑编号，不是物理插口。","supplement_markdown":"FTP 数据连接主动模式用 20；HTTPS 是 443。","content_form":"mixed","chapter":"计算机网络 · 传输层 · 端口与熟知端口","kp_tags":["熟知端口","DNS 53","HTTP 80","FTP 21"],"source_label":"用户上传","images":["media/086c55cd7d8fcd96efc5a386fd3d6fadff9cf0f4cdbf78773ec758e551e51e1a.png"],"diagram":null},{"id":"1b8053bd-2539-4257-9203-21dde820d911","revision":2,"study_area":"cn","title":"码距（海明距离）与检错纠错的两条式子","body_markdown":"**码距（海明距离）**：两码字对应位不同的位数（异或后数 1）。**编码集码距 $l$** = 两两码距的**最小值**。\n\n$$\\text{检 } d \\text{ 位} \\iff l\\ge d+1;\\qquad \\text{纠 } c \\text{ 位} \\iff l\\ge 2c+1$$","supplement_markdown":"总式 $l=d+c+1\\ (d\\ge c)$ 只是并列写法；做题用上面两条反推，纠错力永不超过检错力。","content_form":"mixed","chapter":"计算机网络 · 数据链路层 · 差错控制（码距与检错纠错编码）","kp_tags":["码距","海明距离","检错 d 位错","纠错 c 位错"],"source_label":"用户上传","images":["media/385aee8613536ca3f75ca59cfa97788e63ba6793b073c4237f606380fb5b573e.png"],"diagram":null},{"id":"4684c0f4-748b-4717-ba00-7b2abadcd639","revision":2,"study_area":"cn","title":"纯确认报文不消耗序号","body_markdown":"纯确认报文（不含数据、无 SYN/FIN）不消耗序号。","supplement_markdown":"会消耗序号的三样：携带数据、SYN（占 1）、FIN（占 1）。","content_form":"mixed","chapter":"计算机网络 · 传输层 · TCP 序号与确认号（何时消耗序号）","kp_tags":["纯确认 ACK","不消耗序号","SYN/FIN","TCP 序号"],"source_label":"用户上传","images":["media/6cbe3a84941de9923a91191c45d708f22f4655a926c2db98e589c9fd8d5d5820.png"],"diagram":null},{"id":"ffff17e7-894e-4410-9dba-7640d58c616f","revision":2,"study_area":"cn","title":"透明传输的两种方法：字节填充与比特填充","body_markdown":"透明传输两种方法：**字节填充**（定界符前补 ESC）与**比特填充**（5 个连续 1 后补 0）。","supplement_markdown":"判据相同：数据里可能出现帧定界符就得处理。","content_form":"mixed","chapter":"计算机网络 · 数据链路层 · 封装成帧与透明传输","kp_tags":["透明传输","字节填充","比特填充","帧定界符"],"source_label":"用户上传","images":["media/b48f53d579bbabf62829ada7b23c3ca1f3e9ae368d301754e6e188dfda5e5151.png"],"diagram":null},{"id":"78205ff9-399b-4df4-ac1d-ea287cd36968","revision":2,"study_area":"co","title":"CPU 性能由三个要素共同决定（f、CPI、IC）","body_markdown":"**CPU 性能三要素**：① 时钟频率 $f$（工艺决定）② CPI（体系结构与指令集决定）③ 指令条数 IC（指令集与编译器决定）。\n\n$$\\text{CPU 时间}=\\frac{IC\\times CPI}{f}$$","supplement_markdown":"「CPI 与谁无关」选时钟频率——主频再高也不改 CPI。","content_form":"mixed","chapter":"计算机组成原理 · 计算机系统概述 · 性能指标（CPU 性能三要素）","kp_tags":["时钟频率","CPI","指令条数 IC","CPU 性能"],"source_label":"用户上传","images":["media/3cf7987db33f44d02a8b417ccea96b5fac17cb1e6081339394cb99134097547f.png"],"diagram":null},{"id":"8d5d664a-6bc5-4a6f-944c-04f7444cc68a","revision":1,"study_area":"co","title":"IEEE 754 的四种舍入模式","body_markdown":"1. **就近舍入（向偶数舍入）**：即十进制的「四舍五入」，余位恰好一半时使末位为偶。\n2. **朝 0 舍入**：朝数轴零点方向舍入，直接截尾。\n3. **朝正无穷舍入（向上舍入）**：正数余位不全为 0 就进位，负数直接截尾。\n4. **朝负无穷舍入（向下舍入）**：负数向最低有效位进 1，正数余位不全为 0 则简单截尾。","supplement_markdown":"只有「就近」要看余位的具体数值，另外三种只看符号和「余位是否为 0」。","content_form":"mixed","chapter":"计算机组成原理 · 数据的表示和运算 · 浮点加减中的舍入（IEEE 754 四种模式）","kp_tags":["就近取偶","朝 0 舍入","朝正/负无穷舍入"],"source_label":"用户上传","images":["media/59ef5df1405edcf3357fa79aa8daf8b9f4facd7ddac4fb04ef0fef8fd06d37c4.png"],"diagram":null},{"id":"ddaed019-7775-459e-aa82-4f451561b4b2","revision":1,"study_area":"co","title":"long 的长度随位宽变，double 不变","body_markdown":"- 长整型 `long` / `unsigned long`：32 位下 4 字节，64 位下 8 字节。\n- 双精度浮点型 `double`：32 位与 64 位下都是 8 字节。","supplement_markdown":"换位宽会变长的只有 long 一类和指针，int、short、float 都不变。","content_form":"mixed","chapter":"计算机组成原理 · 数据的表示和运算 · C 语言数据类型与长度","kp_tags":["long 长度","double 长度","32/64 位模型"],"source_label":"用户上传","images":["media/444b8f4078ee7bba8f7bcd1aac27ff1b3445cd10fc32b0f573dba86bdce3e257.png"],"diagram":null},{"id":"d42a516b-85c6-481f-9a55-3ee5ac2e6bc5","revision":2,"study_area":"co","title":"x86 主要通用寄存器与 16/32 位对应","body_markdown":"**x86 通用寄存器（16→32 位）**\n\n| 16 | 32 | 用途 |\n| --- | --- | --- |\n| AX | EAX | 累加器 |\n| BX | EBX | 基址 |\n| CX | ECX | 计数 |\n| DX | EDX | 数据 |\n| — | ESI/EDI | 变址 |\n| — | EBP/ESP | 栈基址/栈顶 |","supplement_markdown":"E=Extended；AX 等可拆 AH/AL 等 8 位；ESP 指栈顶、EBP 指栈帧基址。","content_form":"mixed","chapter":"计算机组成原理 · 指令系统 · x86 通用寄存器","kp_tags":["x86寄存器","AX/EAX","AH/AL","ESI/EDI/EBP/ESP"],"source_label":"用户上传","images":["media/3a9f12b81898367954570824458ad3f330ae3ee0a10f54d5d40465c8022a1d4d.png"],"diagram":null},{"id":"76414138-ce75-40a1-b3be-42157fb5d00f","revision":2,"study_area":"co","title":"中断处理中硬件与操作系统的分工（断点与现场）","body_markdown":"中断处理分工：**硬件**保存断点（PC、PSW），**操作系统**保存通用寄存器等现场并处理。IDT 的基址由 IDTR 保存。","supplement_markdown":"「保存断点靠硬件、保存现场靠软件」是常考分工点。","content_form":"mixed","chapter":"计算机组成原理 · 输入/输出系统 · 程序中断方式（中断隐指令与中断处理过程）","kp_tags":["中断隐指令","断点 PC/PSW","保存现场","IDTR"],"source_label":"用户上传","images":["media/29d2d9d497105c2d1ace065ac3f09237e4a8735a3364508e0684a726731ce5cb.png"],"diagram":null},{"id":"c6749c9d-ea83-4ada-9a39-3a275b8d696e","revision":2,"study_area":"co","title":"存储字长：一个存储单元的位数，通常等于 MDR 的位数","body_markdown":"**存储字长**：一个存储单元存的二进制位数，通常等于 MDR 位数。","supplement_markdown":"三兄弟：机器字长=CPU 一次处理位数；指令字长=一条指令位数；存储字长=一个存储单元位数。","content_form":"mixed","chapter":"计算机组成原理 · 计算机系统概述 · 机器字长/存储字长/指令字长","kp_tags":["存储字长","存储单元","MDR","机器字长/指令字长"],"source_label":"用户上传","images":["media/b081c03f2ae8f9cd2ee5efe20fa539dc353edd20d44f36fdd726199309af82f8.png"],"diagram":null},{"id":"e06a60de-62ba-48e5-a1e2-c505ac21f584","revision":2,"study_area":"co","title":"容量单位按 2 的幂、速率单位按 10 的幂","body_markdown":"**单位换算**：存储容量按 2 的幂（$1K=2^{10}=1024$）；速率/频率按 10 的幂（$1k=10^3=1000$）。","supplement_markdown":"硬盘标称按 10 的幂、系统按 2 的幂算，所以显示容量比标称小。","content_form":"mixed","chapter":"计算机组成原理 · 计算机系统概述 · 性能指标与硬件规格","kp_tags":["单位换算","2的幂","10的幂","存储容量与速率"],"source_label":"用户上传","images":["media/3e8b5e17f44d071be5c8e0b299651b309148c6ef4b69b88c02b97485dd87caad.png"],"diagram":null},{"id":"f9993309-4a7b-46ee-8340-03991183e3bc","revision":1,"study_area":"co","title":"数据对齐的根本原因：访存以 8 字节块为单位","body_markdown":"并行访问以连续 8 字节为单位，每次读取的数据只能来自地址对齐的块（$0\\sim7$、$8\\sim15$、$\\ldots$、$8k\\sim 8k+7$ 单元）。\n\n访问一个 int（4 字节）时起始地址未对齐就要跨两个块、**两次访存**；按 4 字节对齐则一次完成——这就是内存访问要求数据对齐的根本原因。","supplement_markdown":"判据一句话：起始地址是访问宽度的整数倍，就不会跨块。","content_form":"mixed","chapter":"计算机组成原理 · 数据的表示和运算 · 数据对齐与存储排布","kp_tags":["数据对齐","访存单位","跨块两次访存"],"source_label":"用户上传","images":["media/1b204d9bb24d77c5b8351420d7478ffaf2cacff8d96148eec09ebdc54eecd231.png"],"diagram":null},{"id":"0aef28bc-5678-44c6-bba9-910c3a487eb9","revision":2,"study_area":"co","title":"无符号数溢出看 CF，有符号数手算看范围","body_markdown":"**无符号数溢出看 CF**：最高位向更高位产生进/借位（CF=1）即溢出。**有符号数溢出**可手算看结果是否超出机器字长表示范围。","supplement_markdown":"CF 管无符号（进/借位），OF 管有符号（符号位）；同一条加法各看一个标志。","content_form":"mixed","chapter":"计算机组成原理 · 数据的表示和运算 · 溢出概念及其判别方法","kp_tags":["无符号数溢出","CF 标志位","进位/借位","有符号数溢出"],"source_label":"用户上传","images":["media/19437c37558566ca09e649515066d53ecf91a310c34f72bd9c6a02040c131a33.png"],"diagram":null},{"id":"45594b8d-ad50-45e0-aed8-6209791dc00a","revision":2,"study_area":"co","title":"有符号数溢出判据：OF = C₁ ⊕ C₂","body_markdown":"**有符号溢出判据**：符号位进位 $C_1$ 与最高数值位进位 $C_2$ 不同即溢出：\n\n$$OF=C_1\\oplus C_2$$\n\n只发生在正+正得负（$C_2=1,C_1=0$）或负+负得正（$C_2=0,C_1=1$）。","supplement_markdown":"等价判法：双符号位 $K_1K_2$ 相同未溢出，$01$ 正溢、$10$ 负溢，最高位是真符号。","content_form":"mixed","chapter":"计算机组成原理 · 数据的表示和运算 · 溢出判别（OF = C₁ ⊕ C₂）","kp_tags":["OF 标志位","C1⊕C2","正+正溢出","负+负溢出"],"source_label":"用户上传","images":["media/a30e11295f68ca1fa0bd348bc398ac704d06d4420722088fae15a0fc48a10e35.png"],"diagram":null},{"id":"29843c4d-6349-47f8-a307-55539d95db32","revision":2,"study_area":"co","title":"机器字长与指令字长没有必然关系","body_markdown":"**机器字长与指令字长无必然关系**：机器字长强调参与 ALU 运算的操作数位数，与指令长度（指令字长）无关。","supplement_markdown":"关系：机器字长 $\\ge$ 存储字长（多为整数倍）；指令字长可为存储字长的 1/2、1、2 倍。","content_form":"mixed","chapter":"计算机组成原理 · 计算机系统概述 · 机器字长/存储字长/指令字长","kp_tags":["机器字长","指令字长","ALU 操作数位数","字长倍数关系"],"source_label":"用户上传","images":["media/08ddab037ed8252381c6edf501c7d7d29135728af32cbb0059e107f3069d6fe4.png"],"diagram":null},{"id":"e9a13f8c-9e28-49f4-82d7-640c05b6c8ad","revision":1,"study_area":"co","title":"浮点加减四步：对阶 → 尾数加减 → 规格化 → 舍入","body_markdown":"- **对阶**：小 $e$ 追大 $e$，有效数右移阶差；右移低位可能丢失，需保留保护位、舍入位和粘滞位。\n- **尾数加减**：指数相同后按符号做加法或减法。\n- **规格化**：有效数达 $10.x_2$ 时右移一位、$e$ 加 1；消成 $0.00\\ldots1x_2$ 时左移到首个 1 之前、$e$ 相应减小。\n- **舍入及边界**：常用就近取偶（恰好一半时末位为偶）；最终指数超正常上界才是数值上溢，跌出正常下界先考虑非规格化数，不能直接写成零。","supplement_markdown":"单精度最小正非规格化数是 $2^{-149}$，不是 $2^{-126}$。","content_form":"mixed","chapter":"计算机组成原理 · 数据的表示和运算 · 浮点数的加减运算","kp_tags":["对阶","尾数加减","规格化","舍入"],"source_label":"用户上传","images":["media/e5e2fc2481fab2e6af6705db36a7680f27db67b47d18e8c81ec41d65bbd3c62a.png"],"diagram":null},{"id":"5142d817-87ed-477f-acb2-3e2bcb2a2bea","revision":2,"study_area":"co","title":"浮点运算指标 FLOPS：从 MFLOPS 到 ZFLOPS","body_markdown":"**FLOPS（浮点运算速度，衡量科学计算能力）**：M=$10^6$、G=$10^9$、T=$10^{12}$、P=$10^{15}$、E=$10^{18}$、Z=$10^{21}$ 次/秒。","supplement_markdown":"全是 10 的幂（速率类）；只有存储容量才是 2 的幂，别串。","content_form":"mixed","chapter":"计算机组成原理 · 计算机系统概述 · 性能指标（运算速度：FLOPS）","kp_tags":["FLOPS","MFLOPS/GFLOPS","PFLOPS/EFLOPS","科学计算能力"],"source_label":"用户上传","images":["media/76d608f582c5687f8975fa635b0fc5229a501f3b9efd40084fea75e3e8182b4b.png"],"diagram":null},{"id":"30373ecf-f213-4428-a976-9b34009e1b43","revision":2,"study_area":"ds","title":"B 树高度的上界与下界（底数别取反）","body_markdown":"**$m$ 阶 B 树（$n$ 关键字）高度上下界**：\n\n$$\\log_m(n+1)\\le h\\le \\log_{\\lceil m/2\\rceil}\\frac{n+1}{2}+1$$\n\n下界用满叉 $m$，上界用最瘦 $\\lceil m/2\\rceil$（底数别取反）。","supplement_markdown":"问最大高度往「最瘦」推、最小高度往「最满」推；空结点不算一层。","content_form":"mixed","chapter":"数据结构 · 查找 · B 树（高度与性质）","kp_tags":["B树高度","m 阶","⌈m/2⌉","最瘦与最满"],"source_label":"用户上传","images":["media/53320fc3b8a1abbeea678c56f4d9d81021e88be34e8583d16f714178fc605592.png"],"diagram":null},{"id":"3971636f-0cb6-4851-92a6-216acb8ede8b","revision":2,"study_area":"math2_gaoshu","title":"判断周期函数的四步动作","body_markdown":"**判周期函数四步**：\n1. 逐项求最小正周期（$\\sin(\\omega t+\\varphi)$ 为 $\\frac{2\\pi}{|\\omega|}$）；\n2. 相加/相乘取公共周期（周期之比须为有理数）；\n3. 乘方可减半周期（$\\sin^2 t$ 周期 $\\pi$）；\n4. 含非常数 $t$ 因子（$t\\sin t$ 等）直接判否。","supplement_markdown":"相乘可能压到公倍数一半，如 $\\sin t\\cos t=\\frac12\\sin 2t$ 周期 $\\pi$。","content_form":"mixed","chapter":"高等数学 · 函数、极限、连续 · 函数的基本性质（周期性）","kp_tags":["周期函数","最小正周期","最小公倍数","sin²t"],"source_label":"用户上传","images":["media/2f54d02ebf8c3f88db34e6da05d58c935f5d21024a0ec57c42d64e349fc5c9c0.png"],"diagram":null},{"id":"a083d0d1-b8c7-467c-b3eb-887d382ab14d","revision":3,"study_area":"math2_gaoshu","title":"四条特殊曲线：图形、标准方程与面积/弧长","body_markdown":"**四条特殊曲线**\n- 摆线：$x=a(t-\\sin t),y=a(1-\\cos t)$；面积 $3\\pi a^2$，弧长 $8a$。\n- 星形线：$x=a\\cos^3 t,y=a\\sin^3 t$；$x^{2/3}+y^{2/3}=a^{2/3}$；面积 $\\frac{3\\pi a^2}{8}$，弧长 $6a$。\n- 心形线：$r=a(1+\\cos\\theta)$。\n- 双纽线：$r^2=a^2\\cos 2\\theta$。","supplement_markdown":"摆线一拱弧长与心形线全长都是 $8a$（常考）。","content_form":"mixed","chapter":"高等数学 · 一元函数积分学 · 特殊曲线（面积与弧长）","kp_tags":["摆线","星形线","心形线","双纽线"],"source_label":"用户上传","images":["media/704f89e4a9e8385bb3f94501dd582f97dcb810b59b2ecc21eee87c4c32e62504.png","media/d5805de0a20db4dcec85ec017992509948207ada4767a2a2ec12d7c5cea7b1c6.png"],"diagram":null},{"id":"b19694ab-023e-4837-aed3-32128d2f5282","revision":2,"study_area":"math2_gaoshu","title":"曲率公式：从 Δα/Δs 到 |y″|/(1+y′²)^(3/2)","body_markdown":"**曲率**：$k=\\left|\\frac{d\\alpha}{ds}\\right|=\\frac{|y''|}{(1+{y'}^2)^{3/2}}$；曲率半径 $\\rho=\\frac1k$。","supplement_markdown":"$\\alpha$ 切线倾角、$s$ 弧长；$k$ 越大弯得越厉害。","content_form":"mixed","chapter":"高等数学 · 一元函数微分学 · 曲率与曲率半径","kp_tags":["曲率","Δα/Δs","曲率半径","y''"],"source_label":"用户上传","images":["media/1d603892f2612014a4f689ba03378c7e6698bffc33f4e43a3f133aedc7bdf262.png"],"diagram":null},{"id":"8044951a-e408-4be5-b137-e4c6d085f930","revision":2,"study_area":"math2_gaoshu","title":"连续与间断的四则运算组合结论表","body_markdown":"**连续/间断四则组合**\n\n| 组合 | 结论 |\n| --- | --- |\n| 连续±连续 | 连续 |\n| 连续±间断 | 间断 |\n| 间断±间断 | 不确定 |\n| 连续×连续 | 连续 |\n| 连续×间断(非零) | 间断 |\n| 连续×间断(为零) | 不确定 |\n| 间断×间断 | 不确定 |","supplement_markdown":"除法同乘法（分母非零）；复合在两层都连续时才连续。","content_form":"mixed","chapter":"高等数学 · 函数、极限、连续 · 连续与间断","kp_tags":["连续与间断","四则运算","乘积判据","不确定情形"],"source_label":"用户上传","images":["media/002f35d1ade75d4efb8a3ca84ad07563966a1fd2db4c29287b03d1b54186cb42.png"],"diagram":null},{"id":"40b9b5b0-6628-4f12-89da-c7c675fc0648","revision":2,"study_area":"math2_gaoshu","title":"非奇非偶的兜底公式：对称区间定积分","body_markdown":"**对称区间兜底公式**：\n\n$$\\int_{-a}^{a}f(x)dx=\\int_0^a[f(x)+f(-x)]dx$$\n\n奇函数得 0、偶函数得 $2f(x)$，非奇非偶照样用。","supplement_markdown":"来路：把 $\\int_{-a}^0$ 换元 $x\\to-x$ 并到 $[0,a]$。","content_form":"mixed","chapter":"高等数学 · 一元函数积分学 · 定积分计算（对称区间与奇偶性）","kp_tags":["定积分","对称区间","非奇非偶","偶倍奇零"],"source_label":"用户上传","images":["media/61866685129ec294d14c237bbeb54907273909b75cd21c6f553c8a1978c6c6e0.png"],"diagram":null},{"id":"c0137157-af39-455d-bb5e-1d2af86f06d7","revision":2,"study_area":"math2_xiandai","title":"A 的列向量组线性无关、B 可逆 ⇒ AB 的列向量组仍线性无关","body_markdown":"$A$ 列向量组无关、$B$ 可逆 $\\Rightarrow AB$ 列向量组仍无关。证：$ABx=0\\Rightarrow A(Bx)=0$，$A$ 无关故 $Bx=0$，$B$ 可逆故 $x=0$。","supplement_markdown":"也可看秩：$B$ 可逆不改秩，$r(AB)=r(A)$。","content_form":"mixed","chapter":"线性代数 · 向量 · 线性相关与线性无关","kp_tags":["线性无关","可逆矩阵","齐次方程组只有零解","AB 的列向量组"],"source_label":"用户上传","images":["media/1070c7e975b2a04b9986aa6da60fdf456c0fef4d42a005365d052b7d6fc7e001.png"],"diagram":null},{"id":"4462f0de-c758-452f-961d-866a36981ff6","revision":2,"study_area":"math2_xiandai","title":"n 阶矩阵可对角化的充要条件与充分条件","body_markdown":"$n$ 阶矩阵可对角化 $\\iff$ 有 $n$ 个线性无关特征向量；$n$ 个互异特征值是**充分非必要**条件。","supplement_markdown":"重根时只要每个重根有足够自由未知量（$n-r$ 个）也能对角化。","content_form":"mixed","chapter":"线性代数 · 矩阵的特征值和特征向量 · 矩阵的相似对角化","kp_tags":["可对角化","线性无关特征向量","特征值互不相同","充分条件"],"source_label":"用户上传","images":["media/a63b6860b7affeef8f5caaf7462870ef6b3db906c4328de4cd5e50ee48dacde1.png"],"diagram":null},{"id":"576becdc-7fd1-4796-9278-5790eee4a566","revision":2,"study_area":"math2_xiandai","title":"向量组等价推不出矩阵等价（A、B 等价要同型且等秩）","body_markdown":"**向量组等价 vs 矩阵等价**\n- Ⅰ、Ⅱ 等价 **推不出** $A$、$B$ 等价（$A,B$ 未必同型）；\n- Ⅰ、Ⅱ 等价 **且** $r=s$ $\\Rightarrow$ $A$、$B$ 等价；\n- $A$、$B$ 等价 **推不出** Ⅰ、Ⅱ 等价。\n\n$A\\cong B\\iff$ 同型且 $r(A)=r(B)$。","supplement_markdown":"关键在「同型」：向量组等价只要求互相线性表示。","content_form":"mixed","chapter":"线性代数 · 向量 · 向量组等价","kp_tags":["向量组等价","矩阵等价","同型","r = s"],"source_label":"用户上传","images":["media/f951c57c7da357356db41f091450bbef031dd53f92a0e0110b1a95d681dd2b35.png"],"diagram":null},{"id":"e0addfc1-a55e-4ade-96b2-b30d5eaf0d99","revision":2,"study_area":"math2_xiandai","title":"矩阵等价且行(列)满秩 ⇒ 列(行)向量组等价","body_markdown":"$A\\cong B$ 且**行满秩** $\\Rightarrow$ 列向量组等价（$r(A)=r(B)=m=r(A,B)$）；**列满秩** $\\Rightarrow$ 行向量组等价（$r(A)=r(B)=n=r\\binom{A}{B}$）。","supplement_markdown":"都落在「两组向量等价 $\\iff$ 三个秩相等」这条判据上。","content_form":"mixed","chapter":"线性代数 · 向量 · 向量组等价（满秩时的推论）","kp_tags":["行满秩","列满秩","列向量组等价","三个秩相等"],"source_label":"用户上传","images":["media/f951c57c7da357356db41f091450bbef031dd53f92a0e0110b1a95d681dd2b35.png"],"diagram":null},{"id":"5cda5f4c-cbf6-497a-94f2-8f5811363ab6","revision":2,"study_area":"math2_xiandai","title":"秩的三个常用工具（夹逼出等号）","body_markdown":"**秩三工具**：① $r(A,B)\\le r(A)+r(B)$；② $r(\\alpha_1,\\dots,\\alpha_k)\\le k$；③ $r(A,B)\\ge r(A)$。","supplement_markdown":"常两头夹 $r(A)\\le r(A,B)\\le r(A)+r(B)$，再配 $r(AB)\\le\\min\\{r(A),r(B)\\}$ 逼等号。","content_form":"mixed","chapter":"线性代数 · 矩阵 · 矩阵的秩（常用工具）","kp_tags":["秩的不等式","r(A,B)","秩不超过向量个数","部分秩"],"source_label":"用户上传","images":["media/50e36f93755bb1af729b4a91dd44d259c7074d1b062abb9083c5b89bd1a6ef68.png"],"diagram":null},{"id":"3407f436-62d7-4b68-a27f-f6acb31d3f0f","revision":2,"study_area":"os","title":"PCB 的两种组织方式：链接方式与索引方式","body_markdown":"**PCB 两种组织**\n- **链接方式**：链接指针放在 PCB 内部，同状态进程串成队列（PCB 可离散存放）。\n- **索引方式**：独立的就绪/阻塞索引表指向各 PCB（PCB 可连续存放）。\n- 都有执行指针、就绪/阻塞/空闲队列指针。","supplement_markdown":"差别在「队列记在哪」：链接记在 PCB 内、索引记在表里。","content_form":"mixed","chapter":"操作系统 · 进程管理 · 进程的组织（PCB 的链接与索引方式）","kp_tags":["PCB","链接方式","索引方式","就绪/阻塞队列指针"],"source_label":"用户上传","images":["media/6492ade0746e40e421bb434135c5cd4fb307bc3d8b608fff761f40049c65f01c.png"],"diagram":null},{"id":"0d04d9e9-60b3-4e6c-86b6-c83b529e5020","revision":2,"study_area":"os","title":"内存保护需要硬件与软件配合（上下限/重定位/界地址寄存器）","body_markdown":"**内存保护需软硬件配合**：CPU 设上下限、重定位（基址）、界地址（限长）寄存器等记录合法范围，硬件做地址映射时顺带比较越界。","supplement_markdown":"重定位寄存器存起始物理地址、界地址寄存器存最大长度；不能只靠软件查。","content_form":"mixed","chapter":"操作系统 · 内存管理 · 地址转换与内存保护","kp_tags":["内存保护","重定位寄存器","界地址寄存器","上下限寄存器"],"source_label":"用户上传","images":["media/7add3f09db52ce9c9e5789008ea3a1af4f043cf5059e24a94467742309ffb93a.png"],"diagram":null},{"id":"a9f7a086-9572-40c9-9544-0317c1da6430","revision":2,"study_area":"os","title":"内核空间共享，但每个进程有独立的内核栈","body_markdown":"内核空间共享（代码/数据全系统一份），但**每个进程有独立内核栈**，存内核态函数返回地址、局部变量、中断上下文；内核栈指针在该进程 PCB 中。","supplement_markdown":"「共享」是代码/数据，「独立」是内核栈，两层别混。","content_form":"mixed","chapter":"操作系统 · 操作系统概述 · 运行机制（内核空间与内核栈）","kp_tags":["内核栈","内核空间","中断上下文","PCB"],"source_label":"用户上传","images":["media/70f4bbfe3dc2b1c36a5a18bd16b352772a78f7cf5b01f883718ba52b4d5dca77.png"],"diagram":null},{"id":"6c6d01fe-2844-4de8-bace-fe0e793ffe66","revision":2,"study_area":"os","title":"动态优先级要服务于行为反馈（降级 / 不惩罚 / 老化）","body_markdown":"**动态优先级看行为反馈**\n\n| 事件 | 调整 | 原因 |\n| --- | --- | --- |\n| 时间片用完 | 降低 | 抑制长期占 CPU |\n| I/O 完成 | 保持/提高 | 改善交互响应 |\n| 长期等待 | 提高（老化） | 防饥饿 |\n| 刚被选中 | 不单独奖惩 | 只是调度结果 |","supplement_markdown":"「降低优先级的合理时机」= 时间片用完（2010 统考）。","content_form":"mixed","chapter":"操作系统 · 进程管理 · 典型调度算法（优先级调度与动态优先级）","kp_tags":["动态优先级","时间片用完","老化","防止饥饿"],"source_label":"用户上传","images":["media/927ed81828a4527d754fc4f63bc2c4d18d91569ed146f936786cf3d02a4586b6.png"],"diagram":null},{"id":"de96af22-3908-45be-804f-b43fdac5ea72","revision":2,"study_area":"os","title":"双缓冲：处理一个数据块的平均耗时 Max(T, C+M)","body_markdown":"**双缓冲**：两个缓冲区（各一大小=一块），初始一满一空。处理一个数据块平均耗时 $\\mathrm{Max}(T,\\,C+M)$。","supplement_markdown":"$T$=入缓冲、$M$=缓冲→用户区、$C$=CPU 处理；对照单缓冲 $\\mathrm{Max}(C,T)+M$，双缓冲快在设备与 CPU 并行。","content_form":"mixed","chapter":"操作系统 · 输入/输出管理 · 缓冲区管理（单缓冲与双缓冲）","kp_tags":["双缓冲","缓冲区","Max(T, C+M)","设备与CPU并行"],"source_label":"用户上传","images":["media/b8f818db37ccfe97eac8baa160aa8cedaca29740b1dc53a7679623765e56e2e2.jpg"],"diagram":null},{"id":"1b7d3b2e-b208-4f10-ad74-f20722b6dd94","revision":2,"study_area":"os","title":"引导程序分两种：ROM 自举程序与启动管理器","body_markdown":"**引导程序两种**：① ROM 中的自举程序（BIOS 一部分，启动具体设备）；② 硬盘活动分区引导扇区中的启动管理器（引导操作系统）。","supplement_markdown":"位置是命门：自举在 ROM、启动管理器在活动分区引导扇区。","content_form":"mixed","chapter":"操作系统 · 操作系统概述 · 操作系统引导（BIOS 与启动管理器）","kp_tags":["引导程序","自举程序","BIOS","启动管理器"],"source_label":"用户上传","images":["media/95c4db98b8ba02f1e5964435fb3380599081e412eecee5a6759747e06c16c30e.png"],"diagram":null},{"id":"7e59f7c6-92ca-4a6c-b523-ed055205a871","revision":2,"study_area":"os","title":"键盘数据要经内核缓冲区中转：中断处理 ≠ 系统调用","body_markdown":"键盘输入数据通路（三站）：控制器数据寄存器 →（**中断服务程序**）→ **内核缓冲区** →（**系统调用**）→ 用户缓冲区。设备到内核缓冲区是中断处理，内核到用户缓冲区是系统调用。","supplement_markdown":"「中断服务例程结束时数据放哪」= 内核缓冲区（不能直接写用户空间）。","content_form":"mixed","chapter":"操作系统 · 操作系统概述 · 中断异常与系统调用（内核缓冲区）","kp_tags":["外部中断","中断服务程序","系统调用","内核缓冲区/用户缓冲区"],"source_label":"用户上传","images":["media/5671503a12ede795e524feccd014b7318bb6b5cb5e6083d7b5aaa093adb22fc0.png"],"diagram":null},{"id":"63977abc-7d97-4a72-a328-fa6d0964090d","revision":2,"study_area":"os","title":"高响应比优先：响应比 R = (W+S)/S","body_markdown":"**高响应比优先**（非抢占）：\n\n$$R=\\frac{W+S}{S}=1+\\frac{W}{S}$$\n\n$W$ 已等待、$S$ 预计服务；短任务优先，等久了响应比升高，长任务不饿死。","supplement_markdown":"每次调度算全队列响应比取最大，只在当前作业完成时重算。","content_form":"mixed","chapter":"操作系统 · 进程管理 · 典型调度算法（高响应比优先）","kp_tags":["高响应比优先","响应比","已等待时间 W","预计服务时间 S"],"source_label":"用户上传","images":["media/640f2834fe2105e69a42251953c982f302fc709d92e8a7eae1fad184728b32e5.png"],"diagram":null}]};
